hunks.new:
pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    // `attempt` is 1-based: the first retry is attempt 1 and must wait exactly
    // `base_delay_ms`, so the doubling exponent is `attempt - 1`. Saturating
    // arithmetic keeps huge attempt numbers pinned at `max_delay_ms` instead of
    // overflowing the shift and wrapping down to zero.
    let shift = attempt.saturating_sub(1).min(63);
    let raw = config.base_delay_ms.saturating_mul(1u64 << shift);
    raw.min(config.max_delay_ms)
}

