#[test]
fn large_attempts_saturate_at_the_cap() {
    // The doubling exponent saturates at 63 and the multiplication is
    // saturating, so huge attempt numbers pin at max_delay_ms rather than
    // overflowing the u64 shift and wrapping to zero.
    assert_eq!(next_delay(100, &cfg()), 1_000);
    assert_eq!(next_delay(u32::MAX, &cfg()), 1_000);
}

